12	func (d *DB) UpsertMemoRelation(ctx context.Context, create *store.MemoRelation) (*store.MemoRelation, error) {
13		stmt := `
14			INSERT INTO memo_relation (
15				memo_id,
16				related_memo_id,
17				type
18			)
19			VALUES (?, ?, ?)
20			ON CONFLICT(memo_id, related_memo_id, type) DO UPDATE SET type = excluded.type
21			RETURNING memo_id, related_memo_id, type
22		`
23		memoRelation := &store.MemoRelation{}
24		if err := d.db.QueryRowContext(
25			ctx,
26			stmt,
27			create.MemoID,
28			create.RelatedMemoID,
29			create.Type,
30		).Scan(
31			&memoRelation.MemoID,
32			&memoRelation.RelatedMemoID,
33			&memoRelation.Type,
34		); err != nil {
35			return nil, err
36		}
37	
38		return memoRelation, nil
39	}
